    bytes[0] === 0xff &&
    bytes[1] === 0xd8 &&
    bytes[bytes.length - 2] === 0xff &&
    bytes[bytes.length - 1] === 0xd9
  ) {
    let offset = 2;
    let frame = false;
    while (offset + 4 < bytes.length && bytes[offset] === 0xff) {
      while (bytes[offset] === 0xff) offset++;
      const marker = bytes[offset++];
      const length = bytes[offset] * 256 + bytes[offset + 1];
      if (length < 2 || offset + length >= bytes.length - 2) break;
      if (marker >= 0xc0 && marker <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(marker))
        frame = length >= 8;
      if (marker === 0xda && frame && length >= 6) return mimeType;
      offset += length;
    }
  }
  throw new Error("Image bytes do not match a complete PNG or JPEG response");
}

const item = $input.first(),
  plan = $("Select the queued chart").item.json;
const bytes = await helpers.getBinaryDataBuffer(0, "data");
if (checkedImage(bytes, item.binary?.data?.mimeType) !== "image/png")
  throw Error("QuickChart did not return a PNG.");
return [{ json: plan, binary: item.binary, pairedItem: { item: 0 } }];

function telegramReceipt(message, chatId) {
  if (
    !Number.isSafeInteger(message?.message_id) ||
    message.message_id < 1 ||
    String(message?.chat?.id) !== chatId
  ) {
    throw new Error("Telegram did not confirm this chat reply");
  }
  return { chatId, messageId: String(message.message_id) };
}

const plan = $("Select the queued chart").item.json;
const response = $input.first().json;
if (
  response.ok !== true ||
  (plan.config.reportThread !== null &&
    response.result?.message_thread_id !== plan.config.reportThread)
)
  throw Error("Telegram did not confirm the chart destination.");
const receipt = telegramReceipt(response.result, plan.config.reportChatId);
return [{ json: { ...receipt, key: plan.key }, pairedItem: { item: 0 } }];
